 add(b.amount_entry==='company'?'source_debit_amount':'recipient_expected_amount',Number(b.amount_entry==='company'?b.source_debit_amount:b.recipient_expected_amount)>0,'Enter an amount greater than zero.','0보다 큰 금액을 입력하세요.');
