 if(a?.currency!=='KRW'&&a&&!(mutableCurrency(state)&&a.currency===state.context.invoice_currency))add('company_rate_to_krw',Number(b.company_rate_to_krw)>0,'Enter the KRW accounting rate.','원화 회계 환율을 입력하세요.');
