 if(kind==='supplier'){section.querySelector('.section-title').insertAdjacentHTML('beforeend',`<button class="btn" onclick="BOMPinkFX.open('expense',${id})">${E(T('Operational expense','운영 비용'))}</button>`);let s;try{s=await api(`/api/pink-salt/suppliers/${id}/account-v315`)}catch(_){}const rows=(s?.packaging||s?.state?.packaging||[]).filter(x=>x.outstanding_krw>.005);if(rows.length)section.insertAdjacentHTML('beforeend',`<h4>${E(T('Packaging payables','포장재 미지급금'))}</h4>`+rows.map(x=>`<div class="actions"><span>${E(x.reference)} · KRW ${amount(x.outstanding_krw)}</span><button class="btn" onclick="BOMPinkFX.open('packaging',${x.id})">${E(T('Record payment','지급 기록'))}</button></div>`).join(''))}
 host.appendChild(section);
