 modal(`<h2>${E(T('Reconcile bank and recipient','은행 및 수취 대사'))}</h2><p>${E(T('Enter the actual statement movement and recipient confirmation. A different value requires controlled correction.','실제 명세서 이동액과 수취 확인액을 입력하세요. 금액이 다르면 통제된 수정이 필요합니다.'))}</p><form id="bomFxReconcileForm" data-bom-no-review="1">${field('company_amount_actual','Actual company statement amount','실제 회사 명세서 금액','type="number" min="0" step="0.01" required')}${field('recipient_confirmed_amount','Actual recipient confirmed amount','실제 수취 확인 금액','type="number" min="0" step="0.01" required')}${d.separate_fee?field('separate_fee_actual','Actual separate bank fee','실제 별도 은행 수수료','type="number" min="0" step="0.01" required'):''}${field('reason','Reconciliation note','대사 메모','type="text" required')}<div class="field"><label>${E(T('Evidence','증빙'))}</label><input name="receipt" type="file" accept=".pdf,image/*" required></div><div class="actions"><button type="button" class="btn" onclick="closeModal(true)">${E(T('Cancel','취소'))}</button><button class="btn primary">${E(T('Review & Confirm','검토 및 확인'))}</button></div></form>`);
 const f=document.getElementById('bomFxReconcileForm');f.onsubmit=async e=>{e.preventDefault();if(f.dataset.processing==='1')return;const fd=new FormData(f);if(!await confirmAction({title:T('Confirm reconciliation','대사 확인'),message:T('Match the actual bank statement and recipient confirmation to this immutable transaction.','실제 은행 명세서와 수취 확인을 이 거래 기록과 대사합니다.'),details:[{label:T('Actual company amount','실제 회사 금액'),value:fd.get('company_amount_actual')},{label:T('Actual recipient amount','실제 수취액'),value:fd.get('recipient_confirmed_amount')}]}))return;f.dataset.processing='1';try{await api('/api/pink-salt/fx/transactions/'+id+'/reconcile',{method:'POST',body:fd});closeModalAfterSave();toast(T('Reconciliation recorded.','대사가 기록되었습니다.'));await detail(id)}catch(e){toast(e.message)}finally{delete f.dataset.processing}};
