async function policy(id){const reason=await reasonAction({title:T('Approve currency accounting policy','통화 회계 정책 승인'),message:T('Policy basis: settle invoices at their original carrying value; use explicitly evidenced KRW carrying value for the bank movement; recognize the realized FX difference and evidenced bank fees. This authorizes the policy, while Finance verification and final Posting Control remain mandatory.','정책 기준: 원래 장부가로 송장을 정산하고, 증빙된 은행 이동의 원화 장부가를 사용하며, 실현 환차이와 증빙된 은행 수수료를 인식합니다. 이 승인은 정책에 대한 승인입니다. 재무 검증과 최종 전기 관리는 계속 필수입니다.'),required:true,confirmLabel:T('Approve policy','정책 승인')});if(reason===null)return;try{await api('/api/pink-salt/fx/policy',{method:'POST',headers:{'Content-Type':'application/json','X-CEO-Confirmed':'1','X-CEO-Confirmation-Note':encodeURIComponent(reason)},body:JSON.stringify({approved:true,decision_note:reason})});toast(T('Accounting policy decision recorded.','회계 정책 결정이 기록되었습니다.'));await detail(id)}catch(e){toast(e.message)}}
